package com.finguard.dao;
import com.finguard.model.*;import java.sql.*;import java.util.*;import java.math.*;import java.time.*;
public class TransactionDAO {
 private Transaction row(ResultSet r)throws SQLException{return new Transaction(r.getLong("id"),r.getString("account_id"),r.getString("reference_id"),r.getBigDecimal("amount"),r.getString("currency"),TransactionType.valueOf(r.getString("type")),r.getString("merchant"),r.getTimestamp("transaction_time").toLocalDateTime(),TransactionStatus.valueOf(r.getString("status")),r.getInt("risk_score"),RiskLevel.valueOf(r.getString("risk_level")),Arrays.asList(r.getString("risk_reasons").split("\n")));}
 public boolean referenceExists(Connection c,String ref)throws SQLException{try(var s=c.prepareStatement("SELECT 1 FROM transactions WHERE reference_id=?")){s.setString(1,ref);try(var r=s.executeQuery()){return r.next();}}}
 public List<Transaction> all(Connection c)throws SQLException{var out=new ArrayList<Transaction>();try(var s=c.prepareStatement("SELECT * FROM transactions ORDER BY transaction_time DESC");var r=s.executeQuery()){while(r.next())out.add(row(r));}return out;}
 public Optional<Transaction> byId(Connection c,long id)throws SQLException{try(var s=c.prepareStatement("SELECT * FROM transactions WHERE id=?")){s.setLong(1,id);try(var r=s.executeQuery()){return r.next()?Optional.of(row(r)):Optional.empty();}}}
 public List<Transaction> byAccount(Connection c,String account)throws SQLException{try(var s=c.prepareStatement("SELECT * FROM transactions WHERE account_id=? ORDER BY transaction_time DESC")){s.setString(1,account);try(var r=s.executeQuery()){var a=new ArrayList<Transaction>();while(r.next())a.add(row(r));return a;}}}
 public Transaction insert(Connection c,Transaction t)throws SQLException{try(var s=c.prepareStatement("INSERT INTO transactions(account_id,reference_id,amount,currency,type,merchant,transaction_time,status,risk_score,risk_level,risk_reasons) VALUES(?,?,?,?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setString(1,t.accountId());s.setString(2,t.reference());s.setBigDecimal(3,t.amount());s.setString(4,t.currency().toUpperCase());s.setString(5,t.type().name());s.setString(6,t.merchant());s.setTimestamp(7,Timestamp.valueOf(t.timestamp()));s.setString(8,t.status().name());s.setInt(9,t.riskScore());s.setString(10,t.riskLevel().name());s.setString(11,String.join("\n",t.reasons()));s.executeUpdate();try(var k=s.getGeneratedKeys()){if(k.next())return new Transaction(k.getLong(1),t.accountId(),t.reference(),t.amount(),t.currency(),t.type(),t.merchant(),t.timestamp(),t.status(),t.riskScore(),t.riskLevel(),t.reasons());}}throw new SQLException("Insert did not return ID");}
 public List<Transaction> between(Connection c,LocalDateTime from,LocalDateTime to)throws SQLException{try(var s=c.prepareStatement("SELECT * FROM transactions WHERE transaction_time>=? AND transaction_time<=? ORDER BY transaction_time")){s.setTimestamp(1,Timestamp.valueOf(from));s.setTimestamp(2,Timestamp.valueOf(to));try(var r=s.executeQuery()){var a=new ArrayList<Transaction>();while(r.next())a.add(row(r));return a;}}}
}
